def get_int():
    while True:
        try:
            return int(input())
        except ValueError:
            pass
n = get_int()
while n < 1:
    n = get_int()
for i in range(n):
    print(" " * (n - i - 1) + "#" * (i + 1))

def get_int():
    while True:
        try:
            return int(input())
        except ValueError:
            pass
n = get_int()
while n < 1 or n > 8:
    n = get_int()
for i in range(n):
    print(" " * (n - i - 1) + "#" * (i + 1) + "  " + "#" * (i + 1))

def get_int():
    while True:
        try:
            return int(input())
        except ValueError:
            pass
c = get_int()
while c < 0:
    c = get_int()
n = 0
for coin in (25, 10, 5, 1):
    n += c // coin
    c %= coin
print(n)

def get_num():
    while True:
        s = input().strip()
        if s.isascii() and s.isdigit():
            return s

s = get_num()
total = 0
for i, ch in enumerate(reversed(s)):
    d = int(ch)
    if i % 2 == 1:
        d *= 2
        d = d // 10 + d % 10
    total += d
n = len(s)
if total % 10 != 0:
    print("INVALID")
elif n == 15 and s[:2] in ("34", "37"):
    print("AMEX")
elif n == 16 and s[:2] in ("51", "52", "53", "54", "55"):
    print("MASTERCARD")
elif n in (13, 16) and s[0] == "4":
    print("VISA")
else:
    print("INVALID")

P = dict(zip("ABCDEFGHIJKLMNOPQRSTUVWXYZ", [1, 3, 3, 2, 1, 4, 2, 4, 1, 8, 5, 1, 3, 1, 1, 3, 10, 1, 1, 1, 1, 4, 4, 8, 4, 10]))

def score(word):
    return sum(P.get(c, 0) for c in word.upper())

a = score(input())
b = score(input())
if a > b:
    print("Player 1 wins!")
elif b > a:
    print("Player 2 wins!")
else:
    print("Tie!")

key = input()
if not key.isascii() or not key.isdigit():
    print("Usage: ./caesar key")
else:
    k = int(key) % 26
    text = input()
    out = ""
    for c in text:
        if "a" <= c <= "z":
            out += chr((ord(c) - 97 + k) % 26 + 97)
        elif "A" <= c <= "Z":
            out += chr((ord(c) - 65 + k) % 26 + 65)
        else:
            out += c
    print("ciphertext: " + out)

key = input().upper()
if len(key) != 26 or not (key.isascii() and key.isalpha()) or len(set(key)) != 26:
    print("Invalid key")
else:
    text = input()
    out = ""
    for c in text:
        if "a" <= c <= "z":
            out += key[ord(c) - 97].lower()
        elif "A" <= c <= "Z":
            out += key[ord(c) - 65]
        else:
            out += c
    print("ciphertext: " + out)

names = input().split()
n = int(input())
votes = {c: 0 for c in names}
for _ in range(n):
    v = input().strip()
    if v in votes:
        votes[v] += 1
    else:
        print("Invalid vote.")
m = max(votes.values())
for c in names:
    if votes[c] == m:
        print(c)

names = input().split()
n = int(input())
ballots = [input().split() for _ in range(n)]
out = set()
while True:
    cnt = {c: 0 for c in names if c not in out}
    for b in ballots:
        for c in b:
            if c not in out:
                cnt[c] += 1
                break
    top = max(cnt.values())
    if top * 2 > n:
        print([c for c in cnt if cnt[c] == top][0])
        break
    low = min(cnt.values())
    if all(v == low for v in cnt.values()):
        for c in cnt:
            print(c)
        break
    for c in cnt:
        if cnt[c] == low:
            out.add(c)

names = input().split()
n = int(input())
k = len(names)
pref = [[0] * k for _ in range(k)]
for _ in range(n):
    b = [names.index(x) for x in input().split()]
    for i in range(k):
        for j in range(i + 1, k):
            pref[b[i]][b[j]] += 1
pairs = []
for i in range(k):
    for j in range(k):
        if pref[i][j] > pref[j][i]:
            pairs.append((i, j))
pairs.sort(key=lambda p: -(pref[p[0]][p[1]]))
locked = [[False] * k for _ in range(k)]

def reach(a, b):
    if a == b:
        return True
    return any(locked[a][c] and reach(c, b) for c in range(k))

for w, l in pairs:
    if not reach(l, w):
        locked[w][l] = True
for j in range(k):
    if not any(locked[i][j] for i in range(k)):
        print(names[j])
        break

