h, w = map(int, input().split())
img = []
for _ in range(h):
    img.append([tuple(int(x) for x in p.split(",")) for p in input().split()])
new = []
for i in range(h):
    nr = []
    for j in range(w):
        tot = [0, 0, 0]
        cnt = 0
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
