r = int(input())
header = input().split(",")
strs = header[1:]
rows = [input().split(",") for _ in range(r)]
seq = input().strip()

def longest(seq, s):
    best = 0
    for i in range(len(seq)):
        k = 0
        while seq.startswith(s, i + k * len(s)):
            k += 1
        best = max(best, k)
    return best

counts = [str(longest(seq, s)) for s in strs]
for row in rows:
    if row[1:] == counts:
        print(row[0])
        break
else:
    print("No match")

