CREATE TABLE crime_scene_reports (id INTEGER PRIMARY KEY, year INTEGER, month INTEGER, day INTEGER, street TEXT, description TEXT);
CREATE TABLE interviews (id INTEGER PRIMARY KEY, name TEXT, year INTEGER, month INTEGER, day INTEGER, transcript TEXT);
CREATE TABLE bakery_security_logs (id INTEGER PRIMARY KEY, year INTEGER, month INTEGER, day INTEGER, hour INTEGER, minute INTEGER, activity TEXT, license_plate TEXT);
CREATE TABLE people (id INTEGER PRIMARY KEY, name TEXT, phone_number TEXT, passport_number INTEGER, license_plate TEXT);
INSERT INTO crime_scene_reports VALUES (1,2025,7,26,'Main Street','Vandalism of a bench. Two witnesses.');
INSERT INTO crime_scene_reports VALUES (2,2025,7,28,'Humphrey Street','Theft of the CS50 duck took place at 10:15am at the Humphrey Street bakery. Interviews were conducted with three witnesses who were present at the time; each of their interview transcripts mentions the bakery.');
INSERT INTO crime_scene_reports VALUES (3,2025,7,28,'Oak Street','Littering reported near the park.');
INSERT INTO crime_scene_reports VALUES (4,2025,7,29,'Humphrey Street','Noise complaint at 11pm.');
INSERT INTO interviews VALUES (1,'Ruth',2025,7,28,'Sometime within ten minutes of the theft, I saw the thief get into a car in the bakery parking lot and drive away. If you have security footage from the bakery parking lot, you might want to look for cars that left the parking lot in that time frame.');
INSERT INTO interviews VALUES (2,'Eugene',2025,7,28,'I do not know the thief''s name, but it was someone I recognized. Earlier this morning, before I arrived at the bakery, I saw the thief there withdrawing some money from the ATM on Leggett Street.');
INSERT INTO interviews VALUES (3,'Raymond',2025,7,28,'As the thief was leaving the bakery, they called someone who talked to them for less than a minute. In the call, I heard the thief say that they were planning to take the earliest flight out of Fiftyville tomorrow.');
INSERT INTO interviews VALUES (4,'Lena',2025,7,27,'I found a lost umbrella outside the library.');
